import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<List<Integer>> graph = List.of(List.of(1, 2), List.of(3), List.of(3), List.of());
        boolean[] seen = new boolean[graph.size()];
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        seen[0] = true;
        StringBuilder order = new StringBuilder();
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.append(node).append(' ');
            for (int next : graph.get(node)) {
                if (!seen[next]) {
                    seen[next] = true;
                    queue.add(next);
                }
            }
        }
        System.out.println(order.toString().trim());
    }
}

import java.util.List;

public class Main {
    static void dfs(List<List<Integer>> graph, int node, boolean[] seen, StringBuilder order) {
        seen[node] = true;
        order.append(node).append(' ');
        for (int next : graph.get(node)) {
            if (!seen[next]) {
                dfs(graph, next, seen, order);
            }
        }
    }

    public static void main(String[] args) {
        List<List<Integer>> graph = List.of(List.of(1, 2), List.of(3), List.of(3), List.of());
        StringBuilder order = new StringBuilder();
        dfs(graph, 0, new boolean[graph.size()], order);
        System.out.println(order.toString().trim());
    }
}
